import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const projects: Project[] = [
  { id: 'p1', name: 'Атлас платежей', quota: 42, status: 'active' },
  { id: 'p2', name: 'Каталог поставщиков', quota: 88, status: 'warning' },
  { id: 'p3', name: 'Портал поддержки', quota: 100, status: 'over' },
  { id: 'p4', name: 'Внутренняя аналитика', quota: 15, status: 'active' },
  { id: 'p5', name: 'Мобильный клиент', quota: 67, status: 'warning' },
  { id: 'p6', name: 'Биллинг v2', quota: 30, status: 'active' },
  { id: 'p7', name: 'Экспорт отчётов', quota: 95, status: 'over' },
  { id: 'p8', name: 'Интеграция с CRM', quota: 54, status: 'active' },
  { id: 'p9', name: 'Служба уведомлений', quota: 73, status: 'warning' },
  { id: 'p10', name: 'Архив документов', quota: 12, status: 'active' },
  { id: 'p11', name: 'Панель партнёров', quota: 100, status: 'over' },
  { id: 'p12', name: 'Сервис поиска', quota: 8, status: 'active' },
];

const statusOptions: { value: ProjectStatus; label: string; tone: 'success' | 'warning' | 'danger' }[] = [
  { value: 'active', label: 'В норме', tone: 'success' },
  { value: 'warning', label: 'Близко к лимиту', tone: 'warning' },
  { value: 'over', label: 'Превышена', tone: 'danger' },
];

const pageSize = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(
    statusOptions.map((option) => option.value),
  );
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(statusOptions.map((option) => option.value));
    setPage(1);
  };

  const filteredProjects = useMemo(
    () => projects.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const visibleProjects = filteredProjects.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize,
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <div
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--jx-r-xs)',
        }}
      >
        {statusOptions.map((option) => {
          const isActive = activeStatuses.includes(option.value);
          return (
            <JxChip
              key={option.value}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(option.value)}
              onClick={() => {
                if (!isActive) toggleStatus(option.value);
              }}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по заданным фильтрам"
          message="Попробуйте включить другие статусы, чтобы увидеть расход по проектам."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-xs)' }}>
            {visibleProjects.map((project) => {
              const statusMeta = statusOptions.find((option) => option.value === project.status)!;
              return (
                <div
                  key={project.id}
                  className="jx-row"
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: 'var(--jx-r-sm)',
                    padding: 'var(--jx-r-sm)',
                    background: 'var(--jx-surface)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r-lg)',
                  }}
                >
                  <div
                    style={{
                      minWidth: 0,
                      flex: 1,
                      color: 'var(--jx-text)',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {project.name}
                  </div>
                  <JxProgressCircle value={project.quota} showValue />
                  <JxBadge tone={statusMeta.tone}>{statusMeta.label}</JxBadge>
                </div>
              );
            })}
          </div>

          {pageCount > 1 && (
            <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
          )}
        </>
      )}
    </div>
  );
}

